import {combatWaterCount} from './combat-side-missions.js';
import {combatExtrasPanel,combatStashPanel,combatRewardPanel,combatCacheMarker} from './combat-loot-ui.js';
import {combatMissionInfo,combatMissionWon,combatMissionProgress} from './combat-missions.js';
import {tacticalMap,tacticalBlocked,tacticalPaths,tacticalTargets,tacticalCanOpen} from './combat-grid.js';
import {combatName} from './combat.js';
const tacticEsc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tacticSprites={taei:0,seoyeon:1,yeogyeong:2,soyul:3,iseo:4,dogyeom:5,student:6};
function tacticUnit(state,key,unit,selected,busy){const protectedUnit=key==='protected',enemy=key.startsWith('enemy-'),sprite=enemy?(unit.id%2?7:8):tacticSprites[unit.id]??6,name=protectedUnit?'보호 대상 · 부상 학생':enemy?'좀비 '+unit.id:combatName(state,unit.id);return `<button class="tactic-unit ${protectedUnit?'protected-unit':enemy?'hostile':'friendly'} ${selected===key?'unit-selected':''} ${unit.down||enemy&&unit.balance<=0?'unit-down':''} ${unit.escaped?'unit-escaped':''}" data-unit="${key}" data-action="${protectedUnit?'combatInspect':enemy?'combatEnemy':'combatActor'}" data-value="${enemy?unit.id:key}" style="--ux:${(unit.x+.5)*100/12}%;--uy:${(unit.y+.95)*100/8}%;--depth:${unit.y+2}" aria-label="${tacticEsc(name)} · ${unit.x+1}열 ${unit.y+1}행${enemy?unit.stun?' · 견제 중':'':` · 행동력 ${unit.ap}`}" ${busy?'disabled':''}><span class="tactic-walker"><span class="tactic-sprite" style="--sx:${sprite%3*50}%;--sy:${Math.floor(sprite/3)*50}%"></span></span><span class="tactic-unit-foot"></span><span class="tactic-unit-tag">${enemy?(unit.balance<=0?'제압':unit.stun?'견제 '+unit.stun:'좀비'):protectedUnit?'보호 대상':key==='taei'?'태이':'동료'}${!enemy&&!protectedUnit&&!unit.down?` <i>${'●'.repeat(unit.ap)}${'○'.repeat(2-unit.ap)}</i>`:''}</span>${!enemy&&unit.guard?'<span class="tactic-guard">방어</span>':''}</button>`;}
function tacticCard(state,key,selected,busy){const a=state.combatTrial.actors[key];return `<button class="tactic-card ${selected===key?'selected':''}" data-action="combatActor" data-value="${key}" ${busy?'disabled':''}><span class="battle-face" data-face="${a.id}" aria-hidden="true"></span><span><strong>${tacticEsc(combatName(state,a.id))}</strong><small>${a.escaped?'탈출 완료':a.down?'쓰러짐 · 부축 필요':'행동력 '+a.ap+'/2'}</small><meter min="0" max="100" value="${a.stamina}" aria-label="스태미나 ${a.stamina}"></meter><small>스태미나 ${a.stamina} · 공포 ${a.fear} · 부상 ${a.wounds}</small></span></button>`;}
export function combatGridPage(state,selected='taei',mode='move',more=false,error='',busy=false){
 const b=state.combatTrial,mission= combatMissionInfo(b),won=combatMissionWon(b),a=b.actors[selected],paths=tacticalPaths(state,selected),targets=tacticalTargets(state,selected),playing=b.status==='active',ready=playing&&!busy&&!a.down&&!a.escaped&&a.ap>0&&!(selected==='ally'&&b.carrying);
 const cells=Array.from({length:96},(_,n)=>{const x=n%12,y=Math.floor(n/12),block=tacticalBlocked(x,y),path=paths.find(p=>p.x===x&&p.y===y),exit=(!b.mission||b.mission==='escape')&&tacticalMap.exit.some(c=>c[0]===x&&c[1]===y),door=(!b.mission||b.mission==='escape')&&tacticalMap.door.some(c=>c[0]===x&&c[1]===y),cover=b.cover.some(c=>c.x===x&&c.y===y),danger=b.enemies.some(e=>e.balance>0&&Math.abs(e.x-x)+Math.abs(e.y-y)===1),coverable=mode==='cover'&&path?.path.length===1;
 return `<button class="tactic-cell ${block?'cell-blocked':''} ${ready&&mode==='move'&&path?'cell-reachable':''} ${ready&&coverable?'cell-coverable':''} ${danger?'cell-danger':''} ${exit?'cell-exit':''} ${door?'cell-door':''} ${cover?'cell-cover':''}" style="grid-column:${x+1};grid-row:${y+1}" data-action="combatTile" data-value="${x},${y}" data-route="${path?.path.map(c=>c.join(',')).join(';')??''}" data-cost="${path?.cost??''}" aria-label="${x+1}열 ${y+1}행 · ${block?'장애물':cover?'의자 장애물':exit?'출구':door?'방화문':path?'이동 가능 · '+path.path.length+'칸 · 스태미나 '+path.cost:'바닥'}" ${busy||block||!playing?'disabled':''}>${exit?'<span>탈출</span>':door?`<span>${b.door>=2?'열림':'문 '+b.door+'/2'}</span>`:cover?'<span>의자</span>':''}</button>`;}).join('');
 const modeHint=mode==='move'?'파란 칸 클릭 → 이동 · 점선으로 경로 확인':mode==='cover'?'인접한 빈 칸 클릭 → 의자 배치':'붉은 테두리의 인접한 좀비 클릭 → '+(mode==='shove'?'밀치기':'공격');
 return `<section class="tactical-shell"><header class="tactical-header"><div><span>CAMPUS / SURVIVAL · ${b.survivalContext?.location??'예술동'}</span><h1>${b.survivalContext?.title??mission.title}</h1></div><div class="tactical-header-actions"><span class="tactical-turn">${b.turn}<small> / ${b.limit}턴</small></span><button data-action="openQuick" ${busy?'disabled':''}>저장 · 메뉴</button><button data-action="combatExit" ${busy?'disabled':''}>${b.survivalSortie?'생존 거점':'학교생활 메뉴'}</button></div></header><div class="tactical-goal"><strong>${won?'✓ '+mission.success:b.status==='failed'?'임무 실패':'목표 · '+mission.goal}</strong><span class="tactical-mission-progress">${combatMissionProgress(b)}</span><span>소음 ${b.noise}/6${b.reinforced?' · 뒤쪽 적 합류':' · 6이면 뒤쪽 적 등장'} | 생수 ${combatWaterCount(b)} · 의자 ${b.items.chair}</span></div><div class="tactical-layout"><div class="tactical-field"><div class="tactical-map-tools"><p><i class="blue-key"></i>이동 가능 <i class="red-key"></i>적 근접 위험 ${(!b.mission||b.mission==='escape')?'<i class="gold-key"></i>출구':b.protection?'<i class="protect-key"></i>보호 대상':''}</p><button data-action="combatCenter">선택 인물 위치</button></div><div class="tactical-scroll" tabindex="0" aria-label="전투 지도. 좁은 화면에서는 좌우로 밀어 이동하세요."><div class="tactical-board" data-mode="${mode}" data-door-open="${b.door>=2}" data-busy="${busy}"><div class="tactical-floor" role="img" aria-label="예술동 연습실과 복도 전투 전용 배경"></div><div class="tactical-cells">${cells}</div>${combatCacheMarker(b,busy)}${Object.entries(b.actors).filter(([key])=>!b.carrying||key!=='ally').map(([key,p])=>tacticUnit(state,key,p,selected,busy)).join('')}${b.protection?tacticUnit(state,'protected',b.protection,selected,busy):''}${b.enemies.map(e=>tacticUnit(state,'enemy-'+e.id,e,targets.some(t=>t.id===e.id)&&['strike','shove'].includes(mode)?'enemy-'+e.id:'',busy)).join('')}<div class="tactical-fx" aria-hidden="true"></div></div></div><p class="tactical-map-hint" aria-live="polite">${busy?'행동 연출 중…':playing?modeHint:'전투 종료 · 다시 시작하거나 학교생활 메뉴로 돌아갈 수 있어요.'}</p><div class="tactical-brief" aria-live="polite">${b.log.slice(-3).map(line=>`<p>${tacticEsc(line)}</p>`).join('')}</div></div><aside class="tactical-panel"><div class="tactical-roster">${tacticCard(state,'taei',selected,busy)}${tacticCard(state,'ally',selected,busy)}</div>${playing?combatExtrasPanel(b):''}${error?`<p class="tactical-error" role="alert">${tacticEsc(error)}</p>`:''}${playing?`<div class="tactical-command"><h2>${tacticEsc(combatName(state,a.id))}<small>행동력 ${a.ap}/2</small></h2><p>${a.down?'태이가 옆으로 이동해 부축해야 해요.':a.escaped?'이미 탈출했어요. 남은 동료를 움직여 주세요.':b.carrying&&selected==='ally'?'태이가 부축하며 함께 움직여요.':'한 행동마다 행동력 1 · 이동은 최대 3칸'}</p><div class="tactical-actions">${[['move','이동','최대 3칸 · 칸당 스태미나 2'],['strike','공격','인접한 적 · 스태미나 16 · 소음 2'],['shove','밀치기','인접한 적 · 스태미나 10 · 소음 1']].map(([id,label,detail])=>`<button data-action="combatMode" data-value="${id}" aria-pressed="${mode===id}" ${!ready||id==='strike'&&(a.stamina<16||!targets.length)||id==='shove'&&(a.stamina<10||!targets.length)?'disabled':''}><strong>${label}</strong><small>${detail}</small></button>`).join('')}<button data-action="combatGuard" ${!ready?'disabled':''}><strong>방어 · 숨 고르기</strong><small>스태미나 +12 · 가까운 동료 보호</small></button></div>${(!b.mission||b.mission==='escape')?`<button class="tactical-door-action" data-action="combatDoor" ${!ready||!tacticalCanOpen(state,selected)?'disabled':''}>${b.door>=2?'방화문 열림 · 금색 출구 칸으로 이동':'방화문 열기 '+b.door+'/2 · 문 옆에서 행동력 1'}</button>`:''}<button class="tactical-tool-toggle" data-action="combatTools" ${busy?'disabled':''}>${more?'도구 접기':'도구 · 부축'}</button>${more?`<div class="tactical-tools"><button data-action="combatDrink" ${!ready||!combatWaterCount(b)?'disabled':''}>생수 · 스태미나 +18</button><button data-action="combatMode" data-value="cover" aria-pressed="${mode==='cover'}" ${!ready||!b.items.chair||a.stamina<5?'disabled':''}>의자 배치 · 인접한 빈 칸</button><button data-action="combatLoot" ${!ready||!b.supplyCache||b.supplyCache.recovered||Math.abs(a.x-b.supplyCache.x)+Math.abs(a.y-b.supplyCache.y)>1?'disabled':''}>물자 회수 · 행동력 1</button><button data-action="combatBandage" ${!ready||!(b.stash?.items?.bandage>0)||a.wounds<1?'disabled':''}>붕대 치료 · 보관 ${b.stash?.items?.bandage??0}</button><button data-action="combatRescue" ${!ready||selected!=='taei'||!b.actors.ally.down||b.carrying||Math.abs(a.x-b.actors.ally.x)+Math.abs(a.y-b.actors.ally.y)>1||a.stamina<10?'disabled':''}>쓰러진 동료 부축</button></div>`:''}</div><button class="tactical-end" data-action="combatEndTurn" ${busy?'disabled':''}>적 턴 진행 →<small>${Object.values(b.actors).reduce((sum,p)=>sum+(!p.down&&!p.escaped?p.ap:0),0)>0?'남은 행동력 포기 · 적은 2칸 이동 후 공격':'적은 2칸 이동 후 인접 공격'}</small></button>`:`<div class="tactical-finish"><h2>${won?mission.success:'임무 실패'}</h2><p>${won?'임무 목표를 달성했다.':mission.failure}</p>${combatRewardPanel(b)}<button data-action="${b.survivalSortie?'survivalReturn':'combatSetup'}">${b.survivalSortie?'작전 결과 반영 · 거점 복귀':'새 전투 시작'}</button></div>`}${playing?combatStashPanel(b):''}<details class="tactical-status"><summary>상태 · 최근 전투 기록</summary>${Object.values(b.actors).map(p=>`<p>${tacticEsc(combatName(state,p.id))} · 배고픔 ${p.hunger}, 목마름 ${p.thirst}, 공포 ${p.fear}</p>`).join('')}${b.history.slice(-12).map(h=>`<p><small>${h.turn}턴</small> ${tacticEsc(h.text)}</p>`).join('')}</details></aside></div><p class="tactical-prototype-note">격자 전투 시제품 · 학교생활 기록과 별도로 저장됩니다. 좀비는 적 턴에 최대 2칸 이동하고 인접하면 공격합니다.${b.protection?' 보호 대상을 우선 노립니다.':''}</p></section>`;
}
export async function animateGridCombat(root,frames){
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduced)return;
 const board=root.querySelector('.tactical-board');if(!board)return;const rect=board.getBoundingClientRect(),cw=rect.width/12,ch=rect.height/8;
 // Rewind every mover before playing the enemy-turn sequence so units do not teleport first.
 for(const frame of frames.filter(f=>f.kind==='move')){const unit=board.querySelector(`[data-unit="${frame.unit}"] .tactic-walker`);if(unit)unit.style.transform=`translate(${(frame.from.x-frame.to.x)*cw}px,${(frame.from.y-frame.to.y)*ch}px)`;}
 for(const frame of frames)if(frame.defeated||frame.down)board.querySelector(`[data-unit="${frame.target}"]`)?.classList.remove('unit-down');
 for(const frame of frames){
  const unit=board.querySelector(`[data-unit="${frame.unit}"]`),walker=unit?.querySelector('.tactic-walker');if(!walker)continue;
  if(frame.kind==='move'){
   walker.classList.add('is-walking');const points=[frame.from,...frame.path.map(([x,y])=>({x,y}))];const anim=walker.animate(points.map(p=>({transform:`translate(${(p.x-frame.to.x)*cw}px,${(p.y-frame.to.y)*ch}px)`})),{duration:Math.max(180,frame.path.length*170),easing:'linear',fill:'forwards'});await anim.finished.catch(()=>{});walker.style.transform='';walker.classList.remove('is-walking');anim.cancel();
  }else if(frame.kind==='strike'){
   const target=board.querySelector(`[data-unit="${frame.target}"]`),r=unit.getBoundingClientRect(),tr=target?.getBoundingClientRect(),dx=tr?(tr.x-r.x)*.25:8,dy=tr?(tr.y-r.y)*.25:0;
   const hit=walker.animate([{transform:'translate(0,0)'},{transform:`translate(${dx}px,${dy}px)`},{transform:'translate(0,0)'}],{duration:260});
   if(target){const badge=document.createElement('span');badge.className='tactical-impact';badge.textContent=frame.defeated?'제압':frame.down?'쓰러짐':frame.hit?'타격':'방어 · 회피';target.append(badge);target.querySelector('.tactic-sprite')?.animate([{filter:'brightness(1)'},{filter:'brightness(2.5)'},{filter:'brightness(1)'}],{duration:250});setTimeout(()=>badge.remove(),600);}
   await hit.finished.catch(()=>{});if(frame.defeated||frame.down)target?.classList.add('unit-down');
  }else{await walker.animate([{filter:'brightness(1)'},{filter:'brightness(1.7)'},{filter:'brightness(1)'}],{duration:200}).finished.catch(()=>{});}
 }
}
